when.set-body:
@{
            var b = context.Request.Body.As(preserveContent: true);
            var input = new JArray();
            foreach (var m in (JArray)b["messages"]) {
              var role = (string)m["role"]; if (role == "system") { role = "developer"; }
              input.Add(new JObject(new JProperty("role", role), new JProperty("content", m["content"])));
            }
            var o = new JObject(new JProperty("model", "{{code-deployment}}"), new JProperty("input", input));
            var mx = b["max_completion_tokens"] ?? b["max_tokens"]; if (mx != null) { o["max_output_tokens"] = mx; }
            return o.ToString();
        }

@{
            var r = context.Response.Body.As();
            var text = string.Join("", r["output"].Where(x => (string)x["type"] == "message")
                .SelectMany(x => x["content"]).Where(c => (string)c["type"] == "output_text").Select(c => (string)c["text"]));
            var u = r["usage"];
            return new JObject(
              new JProperty("id", r["id"]), new JProperty("object", "chat.completion"), new JProperty("model", r["model"]),
              new JProperty("choices", new JArray(new JObject(new JProperty("index", 0),
                  new JProperty("message", new JObject(new JProperty("role", "assistant"), new JProperty("content", text))),
                  new JProperty("finish_reason", (string)r["status"] == "completed" ? "stop" : "length")))),
              new JProperty("usage", new JObject(new JProperty("prompt_tokens", u["input_tokens"]),
                  new JProperty("completion_tokens", u["output_tokens"]), new JProperty("total_tokens", u["total_tokens"])))).ToString();
        }
